static const HkCjkFont hk_cjk_fonts[] = {
    {14, hk_cjk_glyphs_14, hk_cjk_rows_14, 7599},
    {18, hk_cjk_glyphs_18, hk_cjk_rows_18, 7599},
};

// Closest full-width CJK font to the requested cell height.
static inline const HkCjkFont *hk_cjk_font(int cell) {
    const HkCjkFont *best = &hk_cjk_fonts[0];
    for (unsigned i = 1; i < sizeof hk_cjk_fonts / sizeof hk_cjk_fonts[0]; i++) {
        int d = hk_cjk_fonts[i].cell - cell, b = best->cell - cell;
        if ((d < 0 ? -d : d) < (b < 0 ? -b : b)) best = &hk_cjk_fonts[i];
    }
    return best;
}

// Glyph for a GBK code (lead | trail << 8); 0 when the character has no bitmap (renders as the ASCII '?').
static inline const HkCjkGlyph *hk_cjk_lookup(const HkCjkFont *f, unsigned code) {
    int lo = 0, hi = f->n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned c = f->glyphs[mid].code;
        if (c < code) lo = mid + 1; else if (c > code) hi = mid - 1; else return &f->glyphs[mid];
    }
    return 0;
}

// True for a GBK lead byte (a two-byte character starts here).
static inline int hk_gbk_lead(uint8_t c) { return c >= 0x81; }
